-- Business Question: What proportion of retail revenue is generated by the top 10% of households (Pareto concentration)?
-- Method: NTILE(10) ranking over lifetime household spend to compute decile revenue share and cumulative Lorenz curve points.

WITH household_spend AS (
    SELECT
        household_key,
        lifetime_spend
    FROM {{ ref('dim_household') }}
),

ranked_deciles AS (
    SELECT
        household_key,
        lifetime_spend,
        NTILE(10) OVER (ORDER BY lifetime_spend DESC) AS spend_decile
    FROM household_spend
),

decile_aggregates AS (
    SELECT
        spend_decile,
        COUNT(household_key) AS household_count,
        ROUND(MIN(lifetime_spend), 2) AS min_spend_in_decile,
        ROUND(MAX(lifetime_spend), 2) AS max_spend_in_decile,
        ROUND(SUM(lifetime_spend), 2) AS decile_revenue
    FROM ranked_deciles
    GROUP BY spend_decile
),

total_rev AS (
    SELECT SUM(decile_revenue) AS grand_total_revenue FROM decile_aggregates
)

SELECT
    d.spend_decile,
    d.household_count,
    d.min_spend_in_decile,
    d.max_spend_in_decile,
    d.decile_revenue,
    ROUND(d.decile_revenue * 100.0 / t.grand_total_revenue, 2) AS pct_revenue_share,
    ROUND(
        SUM(d.decile_revenue) OVER (ORDER BY d.spend_decile ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) * 100.0 / 
        t.grand_total_revenue, 
        2
    ) AS cumulative_revenue_share
FROM decile_aggregates d
CROSS JOIN total_rev t
ORDER BY d.spend_decile;
